public void testGetAliases() throws Exception {
    when(mockCoreContainer.isZooKeeperAware()).thenReturn(true);
    Aliases aliases = Aliases.EMPTY.cloneWithCollectionAlias("alias0", "colA").cloneWithCollectionAlias("alias1", "colB").cloneWithCollectionAliasProperties("alias1", "pkey1", "pvalA");
    when(zkStateReader.getAliases()).thenReturn(aliases);
    ListAliasesResponse response = getAliasesAPI.getAliases();
    assertEquals(aliases.getCollectionAliasMap(), response.aliases);
    assertEquals(aliases.getCollectionAliasProperties("alias0"), response.properties.getOrDefault("alias0", Map.of()));
    assertEquals(aliases.getCollectionAliasProperties("alias1"), response.properties.getOrDefault("alias1", Map.of()));
    assertNull(response.error);
}

