protected SolrQueryRequest captureConvertedV1Request(String v2Path, String v2Method, String v2RequestBody) throws Exception {
    final HashMap<String, String> parts = new HashMap<>();
    final Api api = apiBag.lookup(v2Path, v2Method, parts);
    final SolrQueryResponse rsp = new SolrQueryResponse();
    final LocalSolrQueryRequest req = new LocalSolrQueryRequest(null, Map.of()) {

        @Override
        public List<CommandOperation> getCommands(boolean validateInput) {
            if (v2RequestBody == null)
                return Collections.emptyList();
            return ApiBag.getCommandOperations(new ContentStreamBase.StringStream(v2RequestBody), api.getCommandSchema(), true);
        }

        @Override
        public Collection<ContentStream> getContentStreams() {
            return List.of(new ContentStreamBase.StringStream(v2RequestBody));
        }

        @Override
        public Map<String, String> getPathTemplateValues() {
            return parts;
        }

        @Override
        public String getHttpMethod() {
            return v2Method;
        }
    };
    api.call(req, rsp);
    verify(mockRequestHandler).handleRequestBody(queryRequestCaptor.capture(), any());
    return queryRequestCaptor.getValue();
}

