@Test
public void testEnsembleStatusMock() {
    assumeWorkingMockito();
    ZookeeperStatusHandler zkStatusHandler = mock(ZookeeperStatusHandler.class);
    when(zkStatusHandler.getZkRawResponse("zoo1:2181", "ruok")).thenReturn(Arrays.asList("imok"));
    when(zkStatusHandler.getZkRawResponse("zoo1:2181", "mntr")).thenReturn(Arrays.asList("zk_version	3.5.5-390fe37ea45dee01bf87dc1c042b5e3dcce88653, built on 05/03/2019 12:07 GMT", "zk_avg_latency	1"));
    when(zkStatusHandler.getZkRawResponse("zoo1:2181", "conf")).thenReturn(Arrays.asList("clientPort=2181", "secureClientPort=-1", "thisIsUnexpected", "membership: "));
    when(zkStatusHandler.getZkRawResponse("zoo2:2181", "ruok")).thenReturn(Arrays.asList(""));
    when(zkStatusHandler.getZkRawResponse("zoo3:2181", "ruok")).thenReturn(Arrays.asList("imok"));
    // Actual response from ZK if not whitelisted
    when(zkStatusHandler.getZkRawResponse("zoo3:2181", "mntr")).thenReturn(Arrays.asList("mntr is not executed because it is not in the whitelist."));
    when(zkStatusHandler.getZkRawResponse("zoo3:2181", "conf")).thenReturn(Arrays.asList("clientPort=2181"));
    when(zkStatusHandler.getZkStatus(anyString(), any())).thenCallRealMethod();
    when(zkStatusHandler.monitorZookeeper(anyString())).thenCallRealMethod();
    when(zkStatusHandler.validateZkRawResponse(ArgumentMatchers.any(), any(), any())).thenAnswer(Answers.CALLS_REAL_METHODS);
    ZkDynamicConfig zkDynamicConfig = ZkDynamicConfig.parseLines("server.1=zoo1:2780:2783:participant;0.0.0.0:2181
" + "server.2=zoo2:2781:2784:participant;0.0.0.0:2181
" + "server.3=zoo3:2782:2785:participant;0.0.0.0:2181
" + "version=400000003");
    Map<String, Object> mockStatus = zkStatusHandler.getZkStatus("zoo4:2181,zoo5:2181,zoo6:2181", zkDynamicConfig);
    String expected = "{
" + "  "dynamicReconfig":true,
" + "  "ensembleSize":3,
" + "  "details":[
" + "    {
" + "      "role":"participant",
" + "      "zk_version":"3.5.5-390fe37ea45dee01bf87dc1c042b5e3dcce88653, built on 05/03/2019 12:07 GMT",
" + "      "zk_avg_latency":"1",
" + "      "host":"zoo1:2181",
" + "      "clientPort":"2181",
" + "      "secureClientPort":"-1",
" + "      "ok":true},
" + "    {
" + "      "host":"zoo2:2181",
" + "      "ok":false},
" + "    {
" + "      "host":"zoo3:2181",
" + "      "ok":false}],
" + "  "zkHost":"zoo4:2181,zoo5:2181,zoo6:2181",
" + "  "errors":[
" + "    "Your ZK connection string (3 hosts) is different from the dynamic ensemble config (3 hosts). Solr does not currently support dynamic reconfiguration and will only be able to connect to the zk hosts in your connection string.",
" + "    "Unexpected line in 'conf' response from Zookeeper zoo1:2181: thisIsUnexpected",
" + "    "Empty response from Zookeeper zoo2:2181",
" + "    "Could not execute mntr towards ZK host zoo3:2181. Add this line to the 'zoo.cfg' configuration file on each zookeeper node: '4lw.commands.whitelist=mntr,conf,ruok'. See also chapter 'Setting Up an External ZooKeeper Ensemble' in the Solr Reference Guide."],
" + "  "status":"yellow"}";
    assertEquals(expected, JSONUtil.toJSON(mockStatus));
}

