@Test
public void testMultipleCollections() {
    ReplicaListTransformer replicaListTransformer = Mockito.mock(ReplicaListTransformer.class);
    AllowListUrlChecker checker = Mockito.mock(AllowListUrlChecker.class);
    ModifiableSolrParams params = new ModifiableSolrParams();
    params.set("collection", "collection1,collection2");
    try (ZkStateReader zkStateReader = ClusterStateMockUtil.buildClusterState("csr*sr2csr*", "baseUrl1:8983_", "baseUrl2:8984_")) {
        CloudReplicaSource cloudReplicaSource = new CloudReplicaSource.Builder().collection("collection1").onlyNrt(false).zkStateReader(zkStateReader).replicaListTransformer(replicaListTransformer).allowListUrlChecker(checker).params(params).build();
        assertEquals(3, cloudReplicaSource.getSliceCount());
        List<String> sliceNames = cloudReplicaSource.getSliceNames();
        assertEquals(3, sliceNames.size());
        for (int i = 0; i < cloudReplicaSource.getSliceCount(); i++) {
            String sliceName = sliceNames.get(i);
            assertEquals(1, cloudReplicaSource.getReplicasBySlice(i).size());
            // need a switch here because unlike the testShards* tests which always returns slices in
            // the order they were specified, using the collection param can return slice names in any
            // order
            switch(sliceName) {
                case "collection1_slice1":
                    assertEquals("http://baseUrl1:8983/solr/slice1_replica1/", cloudReplicaSource.getReplicasBySlice(i).get(0));
                    break;
                case "collection1_slice2":
                    assertEquals("http://baseUrl2:8984/solr/slice2_replica2/", cloudReplicaSource.getReplicasBySlice(i).get(0));
                    break;
                case "collection2_slice1":
                    assertEquals("http://baseUrl1:8983/solr/slice1_replica3/", cloudReplicaSource.getReplicasBySlice(i).get(0));
                    break;
            }
        }
    }
}

