@Before
public void setUp() {
    SolrTestCaseJ4.assumeWorkingMockito();
    mockSchemaReader = mock(ZkIndexSchemaReader.class);
    schemaWatcher = new SchemaWatcher(mockSchemaReader);
}

@Test
public void testProcess() throws Exception {
    schemaWatcher.process(new WatchedEvent(EventType.NodeDataChanged, KeeperState.SyncConnected, "/test"));
    verify(mockSchemaReader).updateSchema(schemaWatcher, -1);
}

@Test
public void testDiscardReaderReference() {
    schemaWatcher.discardReaderReference();
    schemaWatcher.process(new WatchedEvent(EventType.NodeDataChanged, KeeperState.SyncConnected, "/test"));
    // after discardReaderReference, SchemaWatcher should no longer hold a ref to the reader
    verifyNoInteractions(mockSchemaReader);
}

private ZkController createZkController(SolrZkClient client) throws KeeperException, InterruptedException {
    assumeWorkingMockito();
    CoreContainer mockAlwaysUpCoreContainer = mock(CoreContainer.class, Mockito.withSettings().defaultAnswer(Mockito.CALLS_REAL_METHODS));
    when(mockAlwaysUpCoreContainer.isShutDown()).thenReturn(// Allow retry on session expiry
    Boolean.FALSE);
    ZkController zkController = mock(ZkController.class, Mockito.withSettings().defaultAnswer(Mockito.CALLS_REAL_METHODS));
    when(zkController.getCoreContainer()).thenReturn(mockAlwaysUpCoreContainer);
    when(zkController.getZkClient()).thenReturn(client);
    Mockito.doAnswer(new Answer<Boolean>() {

        volatile boolean sessionExpired = false;

        @Override
        public Boolean answer(InvocationOnMock invocation) throws Throwable {
            String path = (String) invocation.getArguments()[0];
            perhapsExpired();
            Boolean exists = client.exists(path, true);
            perhapsExpired();
            return exists;
        }

        private void perhapsExpired() throws SessionExpiredException {
            if (!sessionExpired && rarely()) {
                sessionExpired = true;
                throw new KeeperException.SessionExpiredException();
            }
        }
    }).when(zkController).pathExists(Mockito.anyString());
    return zkController;
}

