@Test
public void testMultipleSANEntries() throws SSLPeerUnverifiedException, CertificateParsingException {
    when(mockCertificate.getSubjectAlternativeNames()).thenReturn(List.of(List.of(SANType.EMAIL.getValue(), "user1@example.com"), List.of(SANType.EMAIL.getValue(), "user2@example.com")));
    Map<String, Object> params = Map.of("path", "SAN.email", "filter", Map.of("checkType", "equals", "values", List.of("user1@example.com", "user2@example.com")));
    PathBasedCertPrincipalResolver resolver = new PathBasedCertPrincipalResolver(params);
    Principal result = resolver.resolvePrincipal(mockCertificate);
    assertNotNull(result);
    assertTrue(result.getName().contains("user1@example.com") || result.getName().contains("user2@example.com"));
}

