public void test() {
    Map<String, Set<String>> headers = Map.of("a", Set.of("0"), "b", Set.of("1"), "c", Set.of("2"));
    HttpServletRequest httpServletRequestMock = mock(HttpServletRequest.class);
    HttpServletRequest req = new HttpServletRequestWrapper(httpServletRequestMock) {

        @Override
        public String getHeader(String name) {
            return headers.get(name).iterator().next();
        }

        @Override
        public Enumeration<String> getHeaderNames() {
            return Collections.enumeration(headers.keySet());
        }
    };
    HttpServletRequestGetter httpServletRequestGetter = new HttpServletRequestGetter();
    Iterator<String> it = httpServletRequestGetter.keys(req).iterator();
    Map<String, Set<String>> resultBack = new HashMap<>();
    while (it.hasNext()) {
        String key = it.next();
        resultBack.computeIfAbsent(key, k -> new HashSet<>()).add(httpServletRequestGetter.get(req, key));
    }
    assertEquals(headers, resultBack);
}

