@SuppressWarnings("unchecked")
public void testMultiPartUploadAborted() throws IOException {
    when(clientMock.createMultipartUpload((Consumer<CreateMultipartUploadRequest.Builder>) any())).thenReturn(CreateMultipartUploadResponse.builder().build());
    when(clientMock.uploadPart((UploadPartRequest) any(), (RequestBody) any())).thenThrow(S3Exception.builder().message("fake exception").build());
    S3OutputStream stream = new S3OutputStream(clientMock, "key", "bucket");
    // first time it should throw the exception from S3Client
    org.apache.solr.s3.S3Exception solrS3Exception = assertThrows(org.apache.solr.s3.S3Exception.class, () -> stream.write(largeBuffer));
    assertEquals(S3Exception.class, solrS3Exception.getCause().getClass());
    assertEquals("fake exception", solrS3Exception.getCause().getMessage());
    verify(clientMock).abortMultipartUpload((Consumer<AbortMultipartUploadRequest.Builder>) any());
    // after that, the exception should be because the MPU is aborted
    solrS3Exception = assertThrows(org.apache.solr.s3.S3Exception.class, () -> stream.write(largeBuffer));
    assertEquals(IllegalStateException.class, solrS3Exception.getCause().getClass());
    assertTrue("Unexpected exception message: " + solrS3Exception.getCause().getMessage(), solrS3Exception.getCause().getMessage().contains("Can't upload new parts on a MultipartUpload that was aborted"));
    verify(clientMock).createMultipartUpload((Consumer<CreateMultipartUploadRequest.Builder>) any());
    verify(clientMock).uploadPart((UploadPartRequest) any(), (RequestBody) any());
    verify(clientMock, never()).completeMultipartUpload((Consumer<CompleteMultipartUploadRequest.Builder>) any());
    verify(clientMock, times(2)).abortMultipartUpload((Consumer<AbortMultipartUploadRequest.Builder>) any());
    stream.close();
    verify(clientMock, never()).completeMultipartUpload((Consumer<CompleteMultipartUploadRequest.Builder>) any());
}

